# Use os.walk to search for task_hooks, hook, or submission-related files
import os

def search_files(root, max_depth=5):
    depth = 0
    results = []
    for dirpath, dirnames, filenames in os.walk(root):
        depth += 1
        if depth > max_depth:
            for d in dirnames[:]:
                dirnames.remove(d)
        for f in filenames:
            if 'hook' in f.lower() or 'task' in f.lower() or 'submit' in f.lower() or 'state' in f.lower():
                results.append(os.path.join(dirpath, f))
    return results

